const assinatura = $('GET OS by ID').first().json.value[0].Assinatura || '';

const base64LimpoCliente = assinatura.includes('base64,')
  ? assinatura.split('base64,')[1]
  : assinatura;

return [
  {
    json: {
      base64LimpoCliente
    }
  }
];

// 📥 Pegando os dados do primeiro item da entrada (geralmente vindo de um HTTP Request)
const items = $input.first().json.value;

// 🛑 Verifica se a lista 'items' está vazia ou indefinida
if (!items || items.length === 0) {
  // Retorna um erro indicando que não há dados disponíveis
  return [{ json: { error: "Nenhum item retornado" } }];
}

// 📅 Extrai a primeira data diretamente do primeiro report da lista
const primeiraData = items[0].Data_desse_relat_x00f3_rio;

// 🔁 Processa todos os reports para extrair e converter as datas
const datasOrdenadas = items
  .map(item => ({
    // Armazena a string original da data
    raw: item.Data_desse_relat_x00f3_rio,
    // Converte a string para objeto Date para ordenação
    data: new Date(item.Data_desse_relat_x00f3_rio)
  }))
  // ❌ Remove objetos com datas inválidas (ex: string malformada)
  .filter(entry => !isNaN(entry.data))
  // 🔃 Ordena as datas do item mais antigo para o mais recente
  .sort((a, b) => a.data - b.data);

// 📆 Pega a última data da lista ordenada (a mais recente)
// Usa optional chaining (?) para evitar erro se a lista estiver vazia após o filtro
const ultimaData = datasOrdenadas[datasOrdenadas.length - 1]?.raw;

// ✅ Retorna um único item JSON com a primeira e a última data encontradas
return [
  {
    json: {
      primeiraData,
      ultimaData
    }
  }
];

